files.wherefore.json:
{
 "wherefore": 1,
 "name": "fernhollow",
 "generators": [
  {
   "run": [
    "sh",
    "site.sh"
   ],
   "cwd": "gen",
   "makes": "site/index.html, the landing page"
  }
 ],
 "inventory": {
  "authored": {
   "rules": [
    [
     "wherefore.json",
     "what the corpus is"
    ],
    [
     "facts.txt",
     "THE SOURCE"
    ],
    [
     "gen/*.sh",
     "the generators"
    ]
   ]
  }
 }
}

{
 "wherefore": 1,
 "inventory": {
  "authored": {
   "rules": [
    [
     "wherefore.json",
     "the corpus"
    ],
    [
     "facts.json",
     "what this corpus records"
    ]
   ]
  },
  "captured": {
   "groups": {
    "pack": {
     "files": [
      "pack/model.html"
     ],
     "no_stamp": "taken from the pack's site, which the gate does not read",
     "why": "a copy of the pack's published model",
     "upstream": {
      "url": "https://example.com/release.json",
      "read": {
       "json": "release/version"
      },
      "matches": {
       "file": "facts.json",
       "at": "pack.version"
      }
     }
    }
   }
  }
 }
}
